int main(int argc,char** argv){QCoreApplication application(argc,argv);try{
 if(argc==5&&std::string_view(argv[1])=="--interrupted-child")return interruptedChild(argv[2],argv[3],QString::fromUtf8(argv[4]));if(argc!=5)return 64;
 const Path source=argv[1],parent=argv[2],build=argv[3],sys=argv[4];underlay::privateDirectory(parent);QTemporaryDir owned(QString::fromStdString((parent/"interrupted-styled-XXXXXX").string()));CHECK(owned.isValid());owned.setAutoRemove(false);Path data=owned.path().toStdString();std::cout<<"INTERRUPTED_STYLED_DATA "<<data<<'\n'<<std::flush;auto app=stage(source,data/"stage",build,sys);unsigned cases=0;
 for(const auto& scenario:{QString("pen-one-point"),QString("pen-three-points"),QString("marker-eraser"),QString("toolbar-eraser")}){const bool eraser=scenario.contains("eraser");auto root=data/scenario.toStdString();underlay::privateDirectory(root/"inbox");std::filesystem::copy_file(source/"fixtures/library/authored-three-pages.pdf",root/"inbox/authored.pdf");std::atomic<bool> stop{false};reader::syncLibrary(app,root,stop);auto books=library::documents(root);CHECK(books.size()==1);auto book=books[0];auto features=product::featureDirectory(root,book),docroot=library::documentRoot(root,book.id);
  QProcess child;child.setProgram(QString::fromStdString((sys/"usr/lib/ld-linux-aarch64.so.1").string()));child.setArguments({"--library-path",QString::fromStdString((sys/"usr/lib").string()),QString::fromUtf8(argv[0]),"--interrupted-child",QString::fromStdString(app.string()),QString::fromStdString(root.string()),scenario});child.start();CHECK(child.waitForStarted(5000)&&child.waitForFinished(45000));auto out=child.readAllStandardOutput(),err=child.readAllStandardError();if(child.exitCode()!=78||!out.contains("INTERRUPTED_STYLED_PRESERVED_DRAINED_UNCLEAN_NO_UP")){std::cerr<<out.constData()<<err.constData();CHECK(false);}CHECK(child.exitStatus()==QProcess::NormalExit);
  auto expected=readJson(root/"interrupted-expectation.json");CHECK(expected["scenario"]==scenario);auto resume=reader::readViewResume(docroot,3,{});CHECK(resume.page==1&&!resume.clean);auto paths=archives(features);QByteArray archived;if(eraser){CHECK(paths.size()==1);archived=underlay::readBounded(paths[0],1024*1024);}
  {ux::Shell reopened(app,root,true,false,false);Canvas canvas(reopened);CHECK(reopened.choose(0));canvas.ready();settle(reopened,canvas);CHECK(reopened.page()==1&&reopened.unsaved()==0&&!reopened.failed());CHECK(!reader::readViewResume(docroot,3,{}).clean);verifyPreserved(reopened,expected,features,eraser);auto priorInk=expected["beforeInk"].toString().toLatin1();if(eraser){CHECK(inkHash(reopened)==priorInk&&std::string_view(reopened.styledInk()->status().label)=="INTERRUPTED ERASER RETAINED - ORIGINAL INK UNCHANGED");CHECK(archives(features)==paths&&underlay::readBounded(paths[0],1024*1024)==archived);}else {CHECK(inkHash(reopened)!=priorInk);CHECK(std::string_view(reopened.styledInk()->status().label)=="INTERRUPTED STROKE RECOVERED");}
   // Independent page installation must neither project the partial stroke on
   // page zero nor change its stable ID, exact samples or interrupted marker.
   auto retained=document(reopened)["strokes"].toArray();CHECK(reopened.navigateTo(0));canvas.ready();settle(reopened,canvas);CHECK(document(reopened)["strokes"].toArray()==retained&&inkHash(reopened)==expected["pageZeroInk"].toString().toLatin1());CHECK(reopened.navigateTo(1));canvas.ready();settle(reopened,canvas);verifyPreserved(reopened,expected,features,eraser);CHECK(reopened.finish(5000)&&reopened.unsaved()==0);}
  CHECK(reader::readViewResume(docroot,3,{}).clean);++cases;std::cout<<"PASS "<<scenario.toStdString()<<" terminal_display_cancel=true child_destructor=78 exact_reopen=true actual_samples_only=true interrupted_fence=true\n"<<std::flush;
 }
 CHECK(owned.remove());std::cout<<"INTERRUPTED_STYLED_ROUTE_PASS cases="<<cases<<" actual_shell_display=true one_and_multiple_points=true page_style_geometry_preserved=true marker_toolbar_eraser_not_applied=true repeat_drain_idempotent=true child_reopen=true synthetic_release=NONE vendor_calls=0 provider_calls=NONE raw_input=NONE physical=NOT_RUN\n";return 0;
 }catch(const std::exception& e){std::cerr<<"INTERRUPTED_STYLED_ROUTE_FAIL "<<e.what()<<'\n';return 1;}}
